CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,email,full_name) VALUES(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name')); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'customer'); RETURN new; END; $$;
CREATE OR REPLACE FUNCTION public.decide_admin_request(_request_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.admin_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only admins can decide'; END IF; SELECT * INTO r FROM public.admin_requests WHERE id=_request_id FOR UPDATE; IF r.id IS NULL OR r.status <> 'pending' THEN RAISE EXCEPTION 'Pending request not found'; END IF; UPDATE public.admin_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decided_at=now() WHERE id=_request_id; IF _approve THEN INSERT INTO public.user_roles(user_id,role) VALUES(r.user_id,'admin') ON CONFLICT DO NOTHING; END IF; END; $$;